SELECT

FROM article
WHERE status = 1
AND category = #{category}
ORDER BY publish_time DESC, id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM article
WHERE status = 1
AND category = #{category}

SELECT

FROM article
WHERE status = 1 AND category = #{category}
ORDER BY read_count DESC, id
LIMIT #{size}

SELECT

FROM article
WHERE status = 1 AND category = #{category} AND id <> #{excludeId}
ORDER BY read_count DESC, id
LIMIT #{size}
